<?php require __DIR__.'/../bootstrap.php';require_login();if(plan_limit_reached('projects')){flash('error','Your current plan limit has been reached. Upgrade to continue.');redirect('/pricing/');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare("INSERT INTO projects(user_id,name,description,status,start_date,due_date,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())")->execute([current_user()['id'],post('name'),post('description'),post('status','Active'),post('start_date')?:null,post('due_date')?:null]);increment_counter('projects_created_counter'); log_event('projects_created',(int)current_user()['id']); redirect('/projects/');}$title='New Project';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Name<input name="name" required></label><label>Description<textarea name="description" rows="6"></textarea></label><label>Status<select name="status"><option>Active</option><option>Planning</option><option>Completed</option><option>Archived</option></select></label><button class="btn">Create Project</button><p><a class="btn secondary small" href="/ai/?prompt=Project%20assist%3A%20help%20me%20improve%20this%20project">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>